// Day Gate — weekday check only. msg.noSchool provided upstream as 'on'/'off'.
var days  = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
var today = days[new Date().getDay()];

function getState(entityId) {
    return new Promise(function(resolve) {
        var opts = {
            hostname: '192.168.1.101',
            port:     8123,
            path:     '/api/states/' + entityId,
            method:   'GET',
            headers:  { 'Authorization': 'Bearer ' + env.get('HA_TOKEN') }
        };
        var req = http.request(opts, function(res) {
            var body = '';
            res.on('data', function(c) { body += c; });
            res.on('end', function() {
                try { resolve(JSON.parse(body).state); }
                catch(e) { resolve('unknown'); }
            });
        });
        req.on('error', function() { resolve('unknown'); });
        req.end();
    });
}

return getState('input_boolean.' + today).then(function(dayState) {
    if (dayState !== 'on') return null;
    var isWeekend = (today === 'saturday' || today === 'sunday');
    var noSchool  = !isWeekend && msg.noSchool === 'on';
    msg.noSchool  = noSchool ? 'on' : 'off';
    return noSchool ? [null, msg] : [msg, null];
});

