const info = STAGE_ALERTS[msg.payload];
if (!info) return null;

msg.payload = {
    title: info.title,
    message: info.message,
    data: { sticky: true, channel: 'bambu-errors', importance: 'high' }
};
return msg;

const attrs = (msg.data.new_state && msg.data.new_state.attributes) || {};
const errors = attrs.errors || [];
const count = attrs.Count || errors.length;

if (count === 0 || errors.length === 0) return null;

const lines = errors.map(e => {
    const sev = e.severity ? '[' + e.severity + '] ' : '';
    return '\u2022 ' + sev + (e.description || e.code || 'Unknown error');
}).join('\n');

const wikiUrl = (errors[0] && errors[0].wiki_url) ? errors[0].wiki_url : null;

msg.payload = {
    title: 'Transmogrifier: ' + count + ' HMS Error' + (count !== 1 ? 's' : ''),
    message: lines,
    data: { sticky: true, channel: 'bambu-errors', importance: 'high' }
};

if (wikiUrl) {
    msg.payload.data.url = wikiUrl;
    msg.payload.data.clickAction = wikiUrl;
}

return msg;

const attrs = (msg.data.new_state && msg.data.new_state.attributes) || {};
const err = attrs.error || {};

let message = 'A print error has occurred. Check the printer.';
if (err.description) {
    message = err.description;
} else if (err.code) {
    message = 'Error code: ' + err.code;
}

msg.payload = {
    title: 'Transmogrifier: Print Error',
    message: message,
    data: { sticky: true, channel: 'bambu-errors', importance: 'high' }
};

if (err.wiki_url) {
    msg.payload.data.url = err.wiki_url;
    msg.payload.data.clickAction = err.wiki_url;
}

return msg;
